try {
  const data = JSON.parse(msg.payload);
  const todayIndex = 0;
  const tomorrowIndex = 1;
  msg.openmeteo = {
    // Данные на сегодня
    rain_today: data.daily.precipitation_sum[todayIndex] || 0,
    et0_today: data.daily.et0_fao_evapotranspiration[todayIndex] || 0,
    temp_min_today: data.daily.temperature_2m_min[todayIndex] || 0,
    temp_max_today: data.daily.temperature_2m_max[todayIndex] || 0,
    // Данные на завтра
    rain_tomorrow: data.daily.precipitation_sum[tomorrowIndex] || 0,
    et0_tomorrow: data.daily.et0_fao_evapotranspiration[tomorrowIndex] || 0,
    temp_min_tomorrow: data.daily.temperature_2m_min[tomorrowIndex] || 0,
    temp_max_tomorrow: data.daily.temperature_2m_max[tomorrowIndex] || 0
  };
  msg.topic = 'openmeteo';
} catch (error) {
  msg.payload = { error: 'Ошибка запроса к Open-Meteo' };
  msg.topic = 'openmeteo';
}
return msg;

try {
  const data = JSON.parse(msg.payload);
  msg.topic = 'openfarm';

  // Стандартные рекомендации для газона
  const defaultAdvice = {
    watering: '1-2 раза в неделю, 10-15 л/м²',
    fertilizing: 'NPK 20-5-10 весной и осенью',
    mowing: '3-5 см',
    description: 'Стандартные рекомендации по уходу за газоном'
  };

  if (data.data && data.data.length > 0) {
    // Ищем запись о газоне
    const lawnData = data.data.find(item => {
      const name = item.attributes.name.toLowerCase();
      const commonNames = item.attributes.common_names || [];
      return name.includes('lawn') || 
             commonNames.some(n => n.toLowerCase().includes('lawn')) ||
             name.includes('газон') ||
             commonNames.some(n => n.toLowerCase().includes('газон'));
    });

    if (lawnData) {
      msg.openfarm = {
        watering: lawnData.attributes.watering || defaultAdvice.watering,
        fertilizing: lawnData.attributes.fertilizing || defaultAdvice.fertilizing,
        mowing: lawnData.attributes.mowing_height || defaultAdvice.mowing,
        description: lawnData.attributes.description || defaultAdvice.description
      };
    } else {
      msg.openfarm = defaultAdvice;
    }
  } else {
    msg.openfarm = defaultAdvice;
  }
} catch (e) {
  msg.topic = 'openfarm';
  node.warn('Ошибка парсинга OpenFarm: ' + e);
  // В случае ошибки используем стандартные рекомендации
  msg.openfarm = {
    watering: '1-2 раза в неделю, 10-15 л/м²',
    fertilizing: 'NPK 20-5-10 весной и осенью',
    mowing: '3-5 см',
    description: 'Стандартные рекомендации по уходу за газоном'
  };
}
return msg;

const soilMoisture = msg.payload.soil_moisture || 0;
const soilTemp = msg.payload.soil_temp || 0;
const dailyRain = msg.payload.daily_rain || 0;
const humidity = msg.payload.humidity || 0;
const dewPoint = msg.payload.dew_point || 0;
const windSpeed = msg.payload.wind_speed || 0;
const openmeteo = msg.openmeteo || {
  rain_today: 0, rain_tomorrow: 0,
  temp_min_today: 0, temp_min_tomorrow: 0,
  temp_max_today: 0, temp_max_tomorrow: 0,
  et0_today: 0, et0_tomorrow: 0
};
const openfarm = msg.openfarm || {};

let advice = [];

// Проверка на заморозки по прогнозу OpenMeteo
if (openmeteo.temp_min_today <= 0 || openmeteo.temp_min_tomorrow <= 0) {
  const minTemp = Math.min(openmeteo.temp_min_today, openmeteo.temp_min_tomorrow);
  advice.push(`❄️ **Внимание! Прогноз заморозков!** Минимальная температура воздуха: ${minTemp}°C`);
}

// Проверка точки росы
if (dewPoint >= 15) {
  advice.push(`⚠️ **Точка росы**: Высокая (${dewPoint}°C), риск грибковых заболеваний`);
  if (humidity > 80) {
    advice.push('⚠️ **Рекомендация**: Отложите стрижку до снижения влажности');
  }
  if (soilMoisture > 50) {
    advice.push('⚠️ **Рекомендация**: Проверьте дренаж, возможно требуется аэрация');
  }
} else if (dewPoint >= 10) {
  advice.push(`ℹ️ **Точка росы**: Умеренная (${dewPoint}°C), следите за влажностью`);
}

// Проверка скорости ветра
if (windSpeed >= 15) {
  advice.push(`⚠️ **Ветер**: Сильный (${windSpeed} км/ч), полив не рекомендуется`);
  if (dewPoint >= 15) {
    advice.push('⚠️ **Рекомендация**: При сильном ветре и высокой точке росы риск грибковых заболеваний повышен');
  }
} else if (windSpeed > 5) {
  advice.push(`ℹ️ **Ветер**: Умеренный (${windSpeed} км/ч), полив возможен`);
  if (dewPoint >= 15) {
    advice.push('ℹ️ **Рекомендация**: При умеренном ветре и высокой точке росы полив лучше отложить');
  }
}

// Рекомендации по дренажу на основе осадков и влажности почвы (по датчикам)
const isWarmEnough = openmeteo.temp_min_today > 0 && openmeteo.temp_min_tomorrow > 0;
if (isWarmEnough && (soilMoisture > 50 || dailyRain > 5 || dewPoint >= 15)) {
    let drainageReasons = [];
    if (soilMoisture > 50) {
        drainageReasons.push(`высокая влажность почвы (${soilMoisture}%)`);
    }
    if (dailyRain > 5) {
        drainageReasons.push(`значительные осадки за день (${dailyRain} мм)`);
    }
    if (dewPoint >= 15) {
        drainageReasons.push(`высокая точка росы (${dewPoint}°C)`);
    }
    advice.push(`⚠️ **Дренаж**: Требуется. Причины: ${drainageReasons.join('; ')}`);
}
else if (!isWarmEnough) {
    advice.push('⚠️ **Дренаж**: Не рекомендуется из-за риска заморозков');
}

// Рекомендации по поливу с учетом всех параметров
// Проверяем необходимые условия по порядку
let wateringAdvice = null;

// 1. Проверка влажности почвы (необходимое условие)
if (soilMoisture >= 40) {
    wateringAdvice = '💧 **Полив**: Не требуется, влажность почвы достаточная';
}
// 2. Проверка осадков (необходимое условие)
else if (openmeteo.rain_today >= 5 || openmeteo.rain_tomorrow >= 5) {
    const rainDays = [];
    if (openmeteo.rain_today >= 5) rainDays.push('сегодня');
    if (openmeteo.rain_tomorrow >= 5) rainDays.push('завтра');
    wateringAdvice = `💧 **Полив**: Не требуется, ожидаются осадки ${rainDays.join(' и ')}`;
}
// 3. Проверка скорости ветра (необходимое условие)
else if (windSpeed >= 15) {
    wateringAdvice = '💧 **Полив**: Не рекомендуется из-за сильного ветра';
}
// 4. Проверка точки росы (необходимое условие)
else if (dewPoint >= 15) {
    wateringAdvice = '💧 **Полив**: Не рекомендуется из-за высокой точки росы';
}
// 5. Проверка испаряемости (необходимое условие)
else if (openmeteo.et0_today <= 3) {
    wateringAdvice = '💧 **Полив**: Не требуется, низкая испаряемость';
}
// Если все необходимые условия выполнены, проверяем достаточные условия
else {
    wateringAdvice = '💧 **Полив**: 10-15 л/м² до 10 утра';
}

advice.push(wateringAdvice);

// Рекомендации по удобрениям
let fertilizingAdvice = null;

// 1. Проверка температуры почвы (необходимое условие)
if (soilTemp <= 5) {
    fertilizingAdvice = '🌱 **Удобрения**: Не рекомендуется, температура почвы слишком низкая';
}
// 2. Проверка осадков (необходимое условие)
else if (openmeteo.rain_today >= 1 || openmeteo.rain_tomorrow >= 1) {
    fertilizingAdvice = '🌱 **Удобрения**: Не рекомендуется, ожидаются осадки';
}
// Если все необходимые условия выполнены
else {
    fertilizingAdvice = '🌱 **Удобрения**: Внесите NPK 20-5-10 (30 г/м²)';
}

advice.push(fertilizingAdvice);

// Рекомендации по стрижке
let mowingAdvice = null;

// 1. Проверка температуры почвы (необходимое условие)
if (soilTemp <= 5) {
    mowingAdvice = '✂️ **Стрижка**: Не рекомендуется, температура почвы слишком низкая';
}
// 2. Проверка влажности воздуха (необходимое условие)
else if (humidity >= 80) {
    mowingAdvice = '✂️ **Стрижка**: Не рекомендуется, высокая влажность воздуха';
}
// 3. Проверка точки росы (необходимое условие)
else if (dewPoint >= 15) {
    mowingAdvice = '✂️ **Стрижка**: Не рекомендуется, высокая точка росы';
}
// 4. Проверка скорости ветра (необходимое условие)
else if (windSpeed >= 15) {
    mowingAdvice = '✂️ **Стрижка**: Не рекомендуется, сильный ветер';
}
// Если все необходимые условия выполнены
else {
    mowingAdvice = `✂️ **Стрижка**: ${openfarm.mowing || '3-5 см'}`;
}

advice.push(mowingAdvice);

msg.payload = { advice: advice.join('\n') || 'Сегодня особых действий не требуется.' };
return msg;

const today = new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
const text = `🌿 *Рекомендации на ${today}:*\n${msg.payload.advice}`;
msg.payload = {
  chatId: '-1001548038296',
  type: 'message',
  content: text,
  parse_mode: 'Markdown'
};
return msg;

const soilMoisture = parseFloat(msg.payload.soil_moisture) || 0;
const humidity = parseFloat(msg.payload.humidity) || 0;
const dailyRain = parseFloat(msg.payload.daily_rain) || 0;
const uv = parseFloat(msg.payload.uv) || 0;
const solar = parseFloat(msg.payload.solar) || 0;
const dewPoint = parseFloat(msg.payload.dew_point) || 0;
const windSpeed = parseFloat(msg.payload.wind_speed) || 0;
const openmeteo = msg.openmeteo || { 
  rain_today: 0, rain_tomorrow: 0,
  et0_today: 0, et0_tomorrow: 0,
  temp_min_today: 0, temp_min_tomorrow: 0
};

// Проверяем время начала полива (не раньше 6:00)
const now = new Date();
const currentHour = now.getHours();
const currentMinute = now.getMinutes();

// Проверяем безопасные условия для полива
const isSafeTime = currentHour >= 6 && currentHour < 8; // Полив только с 6:00 до 8:00
const isSafeUV = uv < 2; // UV индекс должен быть меньше 2
const isSafeSolar = solar < 100; // Солнечная радиация должна быть меньше 100 Вт/м²
const isDewPointSafe = dewPoint < 15; // Безопасная точка росы для газона
const isWindSafe = windSpeed < 15; // Безопасная скорость ветра для полива (км/ч)

// Проверяем условия для дренажа
const isWarmEnough = openmeteo.temp_min_today > 0 && openmeteo.temp_min_tomorrow > 0; // нет заморозков
const needsDrainage = isWarmEnough && ( // температура выше нуля И
    soilMoisture > 50 || // высокая влажность почвы ИЛИ
    dailyRain > 5 || // значительные осадки за день ИЛИ
    dewPoint >= 15 // высокая точка росы
);

// Проверяем необходимость полива с учетом всех условий
const needsWatering = soilMoisture < 40 && // низкая влажность почвы
                     humidity < 70 && // низкая влажность воздуха
                     openmeteo.et0_today > 3 && // высокая испаряемость
                     openmeteo.rain_today < 5 && // нет значительных осадков сегодня
                     openmeteo.rain_tomorrow < 5 && // нет значительных осадков завтра
                     isSafeTime && // безопасное время
                     isSafeUV && // безопасный UV индекс
                     isSafeSolar && // безопасная солнечная радиация
                     isDewPointSafe && // безопасная точка росы
                     isWindSafe; // безопасная скорость ветра

// Расчет объема воды для полива (л/м²)
let wateringAmount = 0;
if (needsWatering) {
    // Базовый объем 10-15 л/м² с корректировкой на испаряемость
    wateringAmount = 10 + Math.min(5, openmeteo.et0_today - 3);

    // Корректировка на влажность почвы
    if (soilMoisture < 30) {
        wateringAmount += 2; // Увеличиваем при очень сухой почве
    } else if (soilMoisture > 35) {
        wateringAmount -= 2; // Уменьшаем при почве ближе к нормальной
    }

    // Корректировка на скорость ветра
    if (windSpeed > 5) {
        wateringAmount += Math.min(2, windSpeed / 5); // Увеличиваем при ветре
    }

    // Корректировка на точку росы
    if (dewPoint > 10) {
        wateringAmount -= Math.min(2, (dewPoint - 10) / 2); // Уменьшаем при высокой точке росы
    }

    // Учитываем прогноз осадков на сегодня
    if (openmeteo.rain_today > 0 && openmeteo.rain_today < 5) {
        wateringAmount -= openmeteo.rain_today; // Уменьшаем на объем ожидаемых осадков
    }

    // Ограничиваем минимальное и максимальное значение
    wateringAmount = Math.max(8, Math.min(17, wateringAmount));
}

// Общий объем для всей площади (300 кв.м)
const totalWateringAmount = wateringAmount * 300;

// Сохраняем целевой объем воды и время начала полива
global.set('watering_target_volume', totalWateringAmount);
global.set('watering_start_time', new Date().getTime());

// Добавляем информацию о причинах отказа от полива
const reasons = [];
if (!isSafeTime) {
    reasons.push(`Время полива не подходящее (${currentHour}:${currentMinute})`);
}
if (!isSafeUV) {
    reasons.push(`UV индекс слишком высокий (${uv})`);
}
if (!isSafeSolar) {
    reasons.push(`Солнечная радиация слишком высокая (${solar} Вт/м²)`);
}
if (!isDewPointSafe) {
    reasons.push(`Точка росы слишком высокая (${dewPoint}°C)`);
}
if (!isWindSafe) {
    reasons.push(`Скорость ветра слишком высокая (${windSpeed} км/ч)`);
}

msg.payload = { 
    needsWatering: needsWatering, 
    needsDrainage: needsDrainage, 
    wateringAmountPerSqm: wateringAmount, 
    totalWateringAmount: totalWateringAmount, 
    area: 300, 
    soilMoisture: soilMoisture, 
    humidity: humidity, 
    dailyRain: dailyRain, 
    et0Today: openmeteo.et0_today, 
    rainToday: openmeteo.rain_today, 
    rainTomorrow: openmeteo.rain_tomorrow, 
    uv: uv, 
    solar: solar,
    dewPoint: dewPoint,
    windSpeed: windSpeed,
    currentTime: `${currentHour}:${currentMinute}`, 
    safetyReasons: reasons 
};

return msg;

const reasons = [];

// Определяем причины необходимости дренажа
if (msg.payload.soilMoisture > 50) {
    reasons.push(`высокая влажность почвы (${msg.payload.soilMoisture}%)`);
}

if (msg.payload.dailyRain > 5) {
    reasons.push(`значительные осадки за день (${msg.payload.dailyRain} мм)`);
}

// Форматируем дату
const now = new Date();
const formattedDate = now.toLocaleDateString('ru-RU');

msg.payload = {
    content: `💧 *Требуется дренаж ${formattedDate}*\n` +
             `Причины: ${reasons.join('; ')}`
};

node.status({fill:"yellow", shape:"ring", text:"Требуется дренаж"});

return msg;

// Получаем текущий объем воды из датчика
const currentVolume = parseFloat(msg.payload) || 0;

// Получаем целевой объем и начальный объем
const targetVolume = global.get('watering_target_volume') || 0;
let startVolume = global.get('watering_start_volume');
let startTime = global.get('watering_start_time');

// Если начальный объем еще не установлен, устанавливаем его сейчас
if (startVolume === undefined || startVolume === null) {
    startVolume = currentVolume;
    startTime = new Date().getTime();
    global.set('watering_start_volume', startVolume);
    global.set('watering_start_time', startTime);
    node.status({fill:"blue", shape:"dot", text:"Начало полива"});
}

// Рассчитываем выданный объем воды
const deliveredVolume = currentVolume - startVolume;

// Проверяем на ошибки
if (deliveredVolume < 0) {
    node.error("Ошибка: отрицательный объем воды");
    return [null, null];
}

// Проверяем время полива (максимум 2 часа)
const now = new Date().getTime();
const wateringDuration = (now - startTime) / 60000; // в минутах
const maxDuration = 120; // 2 часа в минутах

// Проверяем условия для остановки полива
const targetReached = deliveredVolume >= targetVolume;
const timeExceeded = wateringDuration >= maxDuration;

// Рассчитываем прогресс полива в процентах
const progressPercent = targetVolume > 0 ? Math.min(100, (deliveredVolume / targetVolume) * 100) : 0;

// Сохраняем текущий прогресс для отображения
global.set('watering_progress', progressPercent.toFixed(0));
global.set('watering_delivered', deliveredVolume.toFixed(0));

// Обновляем статус ноды с более подробной информацией
node.status({
    fill: "blue",
    shape: "dot",
    text: `Прогресс: ${progressPercent.toFixed(0)}%, ${deliveredVolume.toFixed(0)}л из ${targetVolume.toFixed(0)}л, ${Math.round(wateringDuration)} мин`
});

// Если достигли целевого объема или превысили время, останавливаем полив
if (targetReached || timeExceeded) {
    msg.targetReached = targetReached;
    msg.timeExceeded = timeExceeded;
    msg.deliveredVolume = deliveredVolume;
    msg.progressPercent = progressPercent;
    msg.wateringDuration = Math.round(wateringDuration);
    return [msg, null];
} else {
    // Продолжаем мониторинг
    msg.targetReached = false;
    msg.timeExceeded = false;
    msg.deliveredVolume = deliveredVolume;
    msg.progressPercent = progressPercent;
    msg.wateringDuration = Math.round(wateringDuration);
    return [null, msg];
}

// Получаем данные о поливе
const startTime = global.get('watering_start_time');
const deliveredVolume = msg.deliveredVolume || 0;
const targetVolume = global.get('watering_target_volume') || 0;
const wateringDuration = msg.wateringDuration || 0;

// Определяем причину остановки полива
let stopReason = '';
if (msg.targetReached) {
    stopReason = 'достигнут целевой объем воды';
} else if (msg.timeExceeded) {
    stopReason = 'превышено максимальное время полива (2 часа)';
} else {
    stopReason = 'неизвестная причина';
}

// Форматируем дату и время
const now = new Date();
const formattedDate = now.toLocaleDateString('ru-RU');
const formattedTime = now.toLocaleTimeString('ru-RU');

// Процент от целевого объема
const percentDelivered = targetVolume > 0 ? (deliveredVolume / targetVolume) * 100 : 100;

msg.payload = {
    content: `✅ *Полив завершен ${formattedDate} в ${formattedTime}*\n` +
             `Причина: ${stopReason}\n` +
             `Длительность: ${wateringDuration} мин\n` +
             `Выдано воды: ${deliveredVolume.toFixed(0)} л (${percentDelivered.toFixed(0)}% от плана)\n` +
             `Расход: ${(deliveredVolume / 300).toFixed(1)} л/м²`
};

// Очищаем глобальные переменные после завершения
global.set('watering_start_time', null);
global.set('watering_target_volume', null);
global.set('watering_start_volume', null);
global.set('watering_progress', null);
global.set('watering_delivered', null);

node.status({fill:"green", shape:"ring", text:"Полив завершен"});

return msg;

const reasons = [];

// Определяем причины отказа от полива
if (msg.payload.soilMoisture >= 40) {
    reasons.push(`Влажность почвы достаточная (${msg.payload.soilMoisture}%)`);
}

if (msg.payload.rainToday >= 5) {
    reasons.push(`Ожидаются осадки сегодня (${msg.payload.rainToday} мм)`);
}

if (msg.payload.rainTomorrow >= 5) {
    reasons.push(`Ожидаются осадки завтра (${msg.payload.rainTomorrow} мм)`);
}

if (msg.payload.et0Today <= 3) {
    reasons.push(`Низкая испаряемость (ET0: ${msg.payload.et0Today})`);
}

// Добавляем причины, связанные с безопасностью
if (msg.payload.safetyReasons && msg.payload.safetyReasons.length > 0) {
    reasons.push(...msg.payload.safetyReasons);
}

// Форматируем дату
const now = new Date();
const formattedDate = now.toLocaleDateString('ru-RU');

msg.payload = {
    content: `ℹ️ *Полив ${formattedDate} не требуется*\n` +
             `Причины: ${reasons.join('; ')}`
};

node.status({fill:"blue", shape:"ring", text:"Полив не требуется"});

return msg;
